exports.handler=async(event,context)=>{
const info={token:event.headers['x-probe-token'],mode:event.headers['x-probe-mode'],runtimeRequestId:context.awsRequestId,event};
console.log('OWNED_URL_EVENT',JSON.stringify(info));
if(info.mode==='throw') throw new Error('owned-observability-throw');
const statusCode=Number(info.mode)||200;
return {statusCode,headers:{'content-type':'application/json','x-owned-runtime-request-id':context.awsRequestId},body:JSON.stringify(info)};
};
